ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns col Collection_Siebel
---
soapenv#Envelope: {
    soapenv#Header:{},
    soapenv#Body:{
        col#ConsultaFlujoEstadosMasivo:{
            col#Origen: vars.headers.sourceSystem,
            col#DatosConsulta: {( payload map (object, index) ->
                    {
                        col#RequestConsultaFlujoMasivo: {
                            col#Abonado: object.connectionNumber,
                            col#CodigoTramite: object.code,
                            col#FechaActivacion: object.activationDate,
                            col#TipoDocumento: object.idType,
                            col#NumeroDocumento: object.id,
                            col#CuentaFacturacion: object.billingAccountId,
                            col#CuentaServicio: object.serviceAccountId,
                        }
                    }
                )
            },
            col#FlagHistoriaTramite: if (vars.headers.checkOrderHistory == "true") 1 else 0
        }
    }    
}

%dw 2.0
output application/json
---
payload.Envelope.Body.ConsultaFlujoEstadosMasivoResponse.ConsultaFlujoEstadosMasivoResult.*ConsultaFlujoMasivo map (value, index) -> {
    Service: {
        connectionNumber: value.NumeroConexion default "",
        documentType: value.TipoDocumento default "",
        documentId: value.NumeroDocumento default "",
        activationDate: value.FechaActivacion default "",
        tramit: value.Tramite default ""
    },
    (Order: {
        id: value.NumeroPedido default "",
        code: value.CodigoTramite default "",
        startDate: value.FechaIngreso default ""    
    }) if (value.NumeroPedido != null),
    WorkPlan: {
        code: value.CodigoFlujo default "",
        description: value.DescripcionFlujo default ""
    },
    Action: {
        code: value.CodigoRespuesta default "",
        description: value.DescripcionRespuesta default ""
    },
    Resultado: {
        status: "PASS",
        code: if (value.CodigoRespuesta == "1") "SUCCESS" else "FAIL",
        description: if (value.CodigoRespuesta == "1")  "SUCCESS" else "FAIL"
    }
}
